inline servicelib::api::Environment ParseEnvironment(
    std::string_view value) {
  if (value.empty()) return servicelib::api::Environment::kUndefined;
  if (value == "local") return servicelib::api::Environment::kLocal;
  if (value == "debug") return servicelib::api::Environment::kDebug;
  if (value == "staging") return servicelib::api::Environment::kStaging;
  if (value == "production") return servicelib::api::Environment::kProduction;
  throw std::invalid_argument("invalid service environment: " +
                              std::string{value});
}

inline int ParseEnvironmentInt(const char* name, const char* value) {
  int result{};
  const std::string_view text{value};
  const auto [end, error] =
      std::from_chars(text.data(), text.data() + text.size(), result);
  if (error != std::errc{} || end != text.data() + text.size()) {
    throw std::invalid_argument(std::string{"invalid integer in "} + name);
  }
  return result;
}

